import { TriviaQuestion } from '../trivia-types'

export const LITERATURE_QUESTIONS: TriviaQuestion[] = [
  { id: 'lit-1', category: 'literature', difficulty: 'easy', question: 'Who wrote "Romeo and Juliet"?', answer: 'William Shakespeare', options: ['Christopher Marlowe', 'William Shakespeare', 'Ben Jonson', 'John Milton'], explanation: 'Shakespeare wrote Romeo and Juliet around 1594-1596. It is one of his earliest tragedies and remains his most famous love story.' },
  { id: 'lit-2', category: 'literature', difficulty: 'easy', question: 'What is the first book of the Harry Potter series?', answer: 'Harry Potter and the Sorcerer\'s Stone', options: ['Harry Potter and the Chamber of Secrets', 'Harry Potter and the Sorcerer\'s Stone', 'Harry Potter and the Prisoner of Azkaban', 'Harry Potter and the Goblet of Fire'], explanation: 'Published in 1997 in the UK as "Philosopher\'s Stone," it was retitled for the American market. J.K. Rowling was rejected by 12 publishers before Bloomsbury accepted the manuscript.' },
  { id: 'lit-3', category: 'literature', difficulty: 'easy', question: 'Who wrote "The Cat in the Hat"?', answer: 'Dr. Seuss', options: ['Shel Silverstein', 'Dr. Seuss', 'Maurice Sendak', 'Roald Dahl'], explanation: 'Dr. Seuss (Theodor Geisel) published The Cat in the Hat in 1957. He wrote it using only 236 different words to make it accessible for beginning readers.' },
  { id: 'lit-4', category: 'literature', difficulty: 'easy', question: 'In what novel does the character Atticus Finch appear?', answer: 'To Kill a Mockingbird', options: ['The Great Gatsby', 'Of Mice and Men', 'To Kill a Mockingbird', 'The Catcher in the Rye'], explanation: 'Harper Lee published To Kill a Mockingbird in 1960. Atticus Finch, a lawyer defending a Black man in the Depression-era South, is widely regarded as one of the greatest literary heroes.' },
  { id: 'lit-5', category: 'literature', difficulty: 'easy', question: 'Who wrote "A Tale of Two Cities"?', answer: 'Charles Dickens', options: ['Charles Dickens', 'Thomas Hardy', 'Jane Austen', 'George Eliot'], explanation: 'Dickens published A Tale of Two Cities in 1859, set during the French Revolution. Its opening line "It was the best of times, it was the worst of times" is one of the most famous in literature.' },
  { id: 'lit-6', category: 'literature', difficulty: 'easy', question: 'What fairy tale features a girl with a red hood visiting her grandmother?', answer: 'Little Red Riding Hood', options: ['Hansel and Gretel', 'Little Red Riding Hood', 'Goldilocks and the Three Bears', 'Snow White'], explanation: 'Little Red Riding Hood has roots in European oral tradition going back centuries. Charles Perrault published the first written version in 1697, and the Brothers Grimm later published their version in 1812.' },
  { id: 'lit-7', category: 'literature', difficulty: 'easy', question: 'Who wrote "1984"?', answer: 'George Orwell', options: ['Aldous Huxley', 'Ray Bradbury', 'George Orwell', 'H.G. Wells'], explanation: 'George Orwell published 1984 in 1949, just a year before his death. The novel introduced terms like "Big Brother," "doublethink," and "thoughtcrime" into the English language.' },
  { id: 'lit-8', category: 'literature', difficulty: 'easy', question: 'What is the name of the whale in Herman Melville\'s famous novel?', answer: 'Moby Dick', options: ['Captain Ahab', 'Moby Dick', 'Ishmael', 'Queequeg'], explanation: 'Moby-Dick was published in 1851 and was a commercial failure during Melville\'s lifetime. The novel\'s opening line, "Call me Ishmael," is one of the most recognized in American literature.' },
  { id: 'lit-9', category: 'literature', difficulty: 'easy', question: 'Who wrote "Pride and Prejudice"?', answer: 'Jane Austen', options: ['Charlotte Bronte', 'Jane Austen', 'Emily Bronte', 'Mary Shelley'], explanation: 'Jane Austen published Pride and Prejudice in 1813. She originally titled the manuscript "First Impressions" and completed the first draft when she was just 21 years old.' },
  { id: 'lit-10', category: 'literature', difficulty: 'easy', question: 'What children\'s book features a spider named Charlotte?', answer: 'Charlotte\'s Web', options: ['Stuart Little', 'Charlotte\'s Web', 'James and the Giant Peach', 'The Phantom Tollbooth'], explanation: 'E.B. White published Charlotte\'s Web in 1952. The story of Charlotte the spider and Wilbur the pig has sold over 45 million copies worldwide.' },
  { id: 'lit-11', category: 'literature', difficulty: 'easy', question: 'Who is the author of "The Lord of the Rings"?', answer: 'J.R.R. Tolkien', options: ['C.S. Lewis', 'J.R.R. Tolkien', 'Terry Pratchett', 'George R.R. Martin'], explanation: 'Tolkien published The Lord of the Rings in three volumes between 1954 and 1955. He and C.S. Lewis were close friends and fellow members of the literary group the Inklings at Oxford.' },
  { id: 'lit-12', category: 'literature', difficulty: 'easy', question: 'What novel begins with the line "Call me Ishmael"?', answer: 'Moby-Dick', options: ['Moby-Dick', 'The Old Man and the Sea', 'Treasure Island', 'Robinson Crusoe'], explanation: 'Herman Melville\'s Moby-Dick (1851) opens with this iconic three-word sentence. Despite its classic status today, the novel sold only about 3,000 copies during Melville\'s lifetime.' },
  { id: 'lit-13', category: 'literature', difficulty: 'easy', question: 'Who wrote "The Adventures of Tom Sawyer"?', answer: 'Mark Twain', options: ['Mark Twain', 'Louisa May Alcott', 'Jack London', 'Herman Melville'], explanation: 'Mark Twain (Samuel Clemens) published The Adventures of Tom Sawyer in 1876. His pen name comes from a riverboat term meaning two fathoms deep — safe water for navigation.' },
  { id: 'lit-14', category: 'literature', difficulty: 'easy', question: 'In the fairy tale, what does Rumpelstiltskin spin into gold?', answer: 'Straw', options: ['Wool', 'Straw', 'Cotton', 'Silk'], explanation: 'In the Brothers Grimm fairy tale, Rumpelstiltskin spins straw into gold for the miller\'s daughter. She must guess his name within three days to keep her firstborn child.' },
  { id: 'lit-15', category: 'literature', difficulty: 'easy', question: 'Who wrote "Green Eggs and Ham"?', answer: 'Dr. Seuss', options: ['Dr. Seuss', 'Shel Silverstein', 'Eric Carle', 'Maurice Sendak'], explanation: 'Dr. Seuss published Green Eggs and Ham in 1960. He wrote the entire book using only 50 different words, winning a bet with his publisher Bennett Cerf.' },
  { id: 'lit-16', category: 'literature', difficulty: 'easy', question: 'What Shakespeare play features the characters Oberon and Titania?', answer: 'A Midsummer Night\'s Dream', options: ['The Tempest', 'A Midsummer Night\'s Dream', 'Twelfth Night', 'As You Like It'], explanation: 'A Midsummer Night\'s Dream, written around 1595-1596, features Oberon and Titania as the king and queen of the fairies. The mischievous fairy Puck is another beloved character from this comedy.' },
  { id: 'lit-17', category: 'literature', difficulty: 'easy', question: 'Who wrote "Charlie and the Chocolate Factory"?', answer: 'Roald Dahl', options: ['Roald Dahl', 'Dr. Seuss', 'C.S. Lewis', 'Enid Blyton'], explanation: 'Roald Dahl published Charlie and the Chocolate Factory in 1964. Dahl was a British-Norwegian author who also wrote Matilda, James and the Giant Peach, and The BFG.' },
  { id: 'lit-18', category: 'literature', difficulty: 'easy', question: 'What famous novella by Charles Dickens features the character Ebenezer Scrooge?', answer: 'A Christmas Carol', options: ['Oliver Twist', 'A Christmas Carol', 'Great Expectations', 'David Copperfield'], explanation: 'Dickens published A Christmas Carol in 1843. The story of Scrooge being visited by three ghosts on Christmas Eve was so popular it helped revive the celebration of Christmas in England.' },
  { id: 'lit-19', category: 'literature', difficulty: 'easy', question: 'Who wrote "The Odyssey"?', answer: 'Homer', options: ['Virgil', 'Sophocles', 'Homer', 'Aristotle'], explanation: 'Homer composed The Odyssey around the 8th century BC, making it one of the oldest works of Western literature. It follows Odysseus on his ten-year journey home after the Trojan War.' },
  { id: 'lit-20', category: 'literature', difficulty: 'easy', question: 'What dystopian novel features a society that burns books?', answer: 'Fahrenheit 451', options: ['Brave New World', '1984', 'Fahrenheit 451', 'The Handmaid\'s Tale'], explanation: 'Ray Bradbury published Fahrenheit 451 in 1953. The title refers to the temperature at which paper supposedly auto-ignites, though Bradbury later admitted the science was approximate.' },
  { id: 'lit-21', category: 'literature', difficulty: 'easy', question: 'Who created the character Sherlock Holmes?', answer: 'Arthur Conan Doyle', options: ['Agatha Christie', 'Arthur Conan Doyle', 'Edgar Allan Poe', 'Wilkie Collins'], explanation: 'Arthur Conan Doyle introduced Sherlock Holmes in A Study in Scarlet (1887). Holmes lives at 221B Baker Street and is known for his deductive reasoning and his companion Dr. Watson.' },
  { id: 'lit-22', category: 'literature', difficulty: 'easy', question: 'In what country is "Don Quixote" set?', answer: 'Spain', options: ['Italy', 'France', 'Spain', 'Portugal'], explanation: 'Miguel de Cervantes published Don Quixote in 1605, set in the Spanish region of La Mancha. It is often called the first modern novel and follows a man who believes himself to be a knight.' },
  { id: 'lit-23', category: 'literature', difficulty: 'easy', question: 'Who wrote "The Very Hungry Caterpillar"?', answer: 'Eric Carle', options: ['Maurice Sendak', 'Eric Carle', 'Dr. Seuss', 'Shel Silverstein'], explanation: 'Eric Carle published The Very Hungry Caterpillar in 1969. The book has sold over 50 million copies and has been translated into more than 60 languages.' },
  { id: 'lit-24', category: 'literature', difficulty: 'easy', question: 'What is the pen name of Samuel Langhorne Clemens?', answer: 'Mark Twain', options: ['O. Henry', 'Mark Twain', 'Lewis Carroll', 'George Orwell'], explanation: 'Clemens adopted the pen name Mark Twain in 1863. "Mark twain" is a Mississippi River term meaning two fathoms (12 feet) deep, indicating safe water for a steamboat.' },
  { id: 'lit-25', category: 'literature', difficulty: 'easy', question: 'Who wrote "The Lion, the Witch and the Wardrobe"?', answer: 'C.S. Lewis', options: ['J.R.R. Tolkien', 'C.S. Lewis', 'Roald Dahl', 'Philip Pullman'], explanation: 'C.S. Lewis published The Lion, the Witch and the Wardrobe in 1950 as the first Chronicles of Narnia book. Lewis and Tolkien were close friends at Oxford, though Tolkien disliked the Narnia series.' },
  { id: 'lit-26', category: 'literature', difficulty: 'easy', question: 'What novel by F. Scott Fitzgerald features the character Jay Gatsby?', answer: 'The Great Gatsby', options: ['Tender Is the Night', 'The Great Gatsby', 'This Side of Paradise', 'The Beautiful and Damned'], explanation: 'Fitzgerald published The Great Gatsby in 1925, set during the Jazz Age on Long Island. The novel was only a modest success during his lifetime but is now considered a masterpiece of American literature.' },
  { id: 'lit-27', category: 'literature', difficulty: 'easy', question: 'Who wrote the poem "The Raven"?', answer: 'Edgar Allan Poe', options: ['Edgar Allan Poe', 'Walt Whitman', 'Henry Wadsworth Longfellow', 'Emily Dickinson'], explanation: 'Poe published "The Raven" in 1845, and it made him a household name. The poem\'s famous refrain is "Nevermore," spoken by a raven perched above the narrator\'s chamber door.' },
  { id: 'lit-28', category: 'literature', difficulty: 'easy', question: 'How many plays did Shakespeare write?', answer: '37', options: ['27', '37', '47', '52'], explanation: 'Shakespeare wrote approximately 37 plays between the late 1580s and 1613. They are traditionally divided into comedies, histories, and tragedies, though some scholars count 36 or 38 depending on attribution.' },
  { id: 'lit-29', category: 'literature', difficulty: 'easy', question: 'Who wrote "Where the Wild Things Are"?', answer: 'Maurice Sendak', options: ['Eric Carle', 'Shel Silverstein', 'Maurice Sendak', 'Dr. Seuss'], explanation: 'Maurice Sendak published Where the Wild Things Are in 1963. The book won the Caldecott Medal in 1964 and follows a boy named Max who sails to an island of wild creatures.' },
  { id: 'lit-30', category: 'literature', difficulty: 'easy', question: 'In which Shakespeare play does the character Hamlet appear?', answer: 'Hamlet', options: ['Macbeth', 'Hamlet', 'Othello', 'King Lear'], explanation: 'Hamlet, written around 1600-1601, is Shakespeare\'s longest play. The famous "To be, or not to be" soliloquy and the phrase "Something is rotten in the state of Denmark" both come from this tragedy.' },
  { id: 'lit-31', category: 'literature', difficulty: 'easy', question: 'What author created the detective Hercule Poirot?', answer: 'Agatha Christie', options: ['Arthur Conan Doyle', 'Agatha Christie', 'Dorothy L. Sayers', 'Raymond Chandler'], explanation: 'Agatha Christie introduced Hercule Poirot in The Mysterious Affair at Styles (1920). Christie is the best-selling fiction writer of all time, with over two billion copies sold worldwide.' },
  { id: 'lit-32', category: 'literature', difficulty: 'easy', question: 'What classic novel features a character named Scout Finch?', answer: 'To Kill a Mockingbird', options: ['The Catcher in the Rye', 'Lord of the Flies', 'To Kill a Mockingbird', 'A Separate Peace'], explanation: 'Scout (Jean Louise) Finch is the narrator of Harper Lee\'s To Kill a Mockingbird. Lee based the character of Dill on her childhood friend Truman Capote.' },
  { id: 'lit-33', category: 'literature', difficulty: 'easy', question: 'Who wrote "Alice\'s Adventures in Wonderland"?', answer: 'Lewis Carroll', options: ['Lewis Carroll', 'J.M. Barrie', 'L. Frank Baum', 'Kenneth Grahame'], explanation: 'Lewis Carroll (Charles Lutwidge Dodgson) published Alice\'s Adventures in Wonderland in 1865. He was a mathematics lecturer at Oxford and invented the story during a boat trip with the real Alice Liddell.' },
  { id: 'lit-34', category: 'literature', difficulty: 'easy', question: 'What is the last book of the Bible?', answer: 'Revelation', options: ['Jude', 'Revelation', 'Acts', 'Malachi'], explanation: 'The Book of Revelation (also called the Apocalypse) is the final book of the New Testament. Malachi is the last book of the Old Testament, which sometimes causes confusion.' },
  { id: 'lit-35', category: 'literature', difficulty: 'medium', question: 'Which Nobel Prize-winning author wrote "The Old Man and the Sea"?', answer: 'Ernest Hemingway', options: ['Ernest Hemingway', 'John Steinbeck', 'William Faulkner', 'F. Scott Fitzgerald'], explanation: 'Hemingway published The Old Man and the Sea in 1952 and won the Nobel Prize in Literature in 1954. The novella about a Cuban fisherman also won the Pulitzer Prize for Fiction in 1953.' },
  { id: 'lit-36', category: 'literature', difficulty: 'medium', question: 'What is the real name of the author known as George Orwell?', answer: 'Eric Arthur Blair', options: ['Eric Arthur Blair', 'Charles Lutwidge Dodgson', 'Samuel Langhorne Clemens', 'Józef Teodor Konrad Korzeniowski'], explanation: 'Eric Arthur Blair adopted the pen name George Orwell in 1933. He chose "George" as a common English name and "Orwell" after the River Orwell in Suffolk, England.' },
  { id: 'lit-37', category: 'literature', difficulty: 'medium', question: 'Which Shakespeare play contains the line "To be, or not to be, that is the question"?', answer: 'Hamlet', options: ['Macbeth', 'Hamlet', 'Othello', 'King Lear'], explanation: 'This famous soliloquy appears in Act 3, Scene 1 of Hamlet. Prince Hamlet contemplates life, death, and the nature of suffering in what has become the most quoted passage in English literature.' },
  { id: 'lit-38', category: 'literature', difficulty: 'medium', question: 'Who wrote "Brave New World"?', answer: 'Aldous Huxley', options: ['George Orwell', 'Aldous Huxley', 'Ray Bradbury', 'H.G. Wells'], explanation: 'Aldous Huxley published Brave New World in 1932. Unlike Orwell\'s 1984, which depicts control through fear, Huxley\'s dystopia controls people through pleasure, drugs (soma), and engineered contentment.' },
  { id: 'lit-39', category: 'literature', difficulty: 'medium', question: 'What novel features the characters Ralph, Jack, and Piggy stranded on an island?', answer: 'Lord of the Flies', options: ['Robinson Crusoe', 'Lord of the Flies', 'The Swiss Family Robinson', 'Treasure Island'], explanation: 'William Golding published Lord of the Flies in 1954. The novel was rejected by 21 publishers before being accepted, and Golding later won the Nobel Prize in Literature in 1983.' },
  { id: 'lit-40', category: 'literature', difficulty: 'medium', question: 'Which poet wrote "Because I could not stop for Death"?', answer: 'Emily Dickinson', options: ['Emily Dickinson', 'Sylvia Plath', 'Elizabeth Barrett Browning', 'Christina Rossetti'], explanation: 'Emily Dickinson wrote this poem around 1863, but it was not published until 1890, four years after her death. She wrote nearly 1,800 poems, but fewer than a dozen were published during her lifetime.' },
  { id: 'lit-41', category: 'literature', difficulty: 'medium', question: 'What is the setting of "The Catcher in the Rye"?', answer: 'New York City', options: ['Boston', 'New York City', 'Philadelphia', 'Chicago'], explanation: 'J.D. Salinger\'s 1951 novel follows Holden Caulfield wandering through New York City after being expelled from prep school. Salinger was famously reclusive and published his last original work in 1965.' },
  { id: 'lit-42', category: 'literature', difficulty: 'medium', question: 'Who wrote the poem "The Road Not Taken"?', answer: 'Robert Frost', options: ['Walt Whitman', 'Robert Frost', 'William Wordsworth', 'Ralph Waldo Emerson'], explanation: 'Robert Frost published "The Road Not Taken" in 1916. Despite being widely interpreted as a poem about individualism, Frost actually wrote it as a gentle joke about his indecisive friend Edward Thomas.' },
  { id: 'lit-43', category: 'literature', difficulty: 'medium', question: 'In "The Great Gatsby," what color is the light at the end of Daisy\'s dock?', answer: 'Green', options: ['Red', 'White', 'Green', 'Blue'], explanation: 'The green light at the end of Daisy Buchanan\'s dock symbolizes Gatsby\'s hopes and the American Dream. It appears at both the beginning and end of the novel, bookending Gatsby\'s tragic pursuit.' },
  { id: 'lit-44', category: 'literature', difficulty: 'medium', question: 'Which author wrote "One Hundred Years of Solitude"?', answer: 'Gabriel Garcia Marquez', options: ['Gabriel Garcia Marquez', 'Jorge Luis Borges', 'Isabel Allende', 'Mario Vargas Llosa'], explanation: 'Garcia Marquez published One Hundred Years of Solitude in 1967 and won the Nobel Prize in Literature in 1982. The novel is considered a masterpiece of magical realism and Latin American literature.' },
  { id: 'lit-45', category: 'literature', difficulty: 'medium', question: 'What Pulitzer Prize-winning novel tells the story of the Joad family during the Dust Bowl?', answer: 'The Grapes of Wrath', options: ['Of Mice and Men', 'The Grapes of Wrath', 'East of Eden', 'Cannery Row'], explanation: 'John Steinbeck published The Grapes of Wrath in 1939, winning the Pulitzer Prize in 1940. The novel was banned and burned in several places for its sympathetic portrayal of migrant workers.' },
  { id: 'lit-46', category: 'literature', difficulty: 'medium', question: 'Who wrote "Slaughterhouse-Five"?', answer: 'Kurt Vonnegut', options: ['Joseph Heller', 'Kurt Vonnegut', 'Ken Kesey', 'Thomas Pynchon'], explanation: 'Vonnegut published Slaughterhouse-Five in 1969, drawing on his experience as a POW in Dresden during the Allied firebombing in 1945. The novel\'s recurring phrase is "So it goes."' },
  { id: 'lit-47', category: 'literature', difficulty: 'medium', question: 'What literary movement emphasized emotion, nature, and individualism in the late 18th and early 19th centuries?', answer: 'Romanticism', options: ['Realism', 'Romanticism', 'Naturalism', 'Modernism'], explanation: 'Romanticism emerged as a reaction against the rationalism of the Enlightenment. Key Romantic writers include Wordsworth, Coleridge, Shelley, Keats, and Byron in England, and Emerson and Thoreau in America.' },
  { id: 'lit-48', category: 'literature', difficulty: 'medium', question: 'Who wrote "Frankenstein"?', answer: 'Mary Shelley', options: ['Mary Shelley', 'Bram Stoker', 'Edgar Allan Poe', 'Ann Radcliffe'], explanation: 'Mary Shelley published Frankenstein in 1818 when she was just 20 years old. She conceived the story during a ghost-story competition at Lord Byron\'s villa on Lake Geneva in 1816.' },
  { id: 'lit-49', category: 'literature', difficulty: 'medium', question: 'What is the longest of Shakespeare\'s plays?', answer: 'Hamlet', options: ['King Lear', 'Hamlet', 'Othello', 'Richard III'], explanation: 'Hamlet runs approximately 4,042 lines, making it Shakespeare\'s longest play. A full uncut performance takes about four and a half hours, which is why most productions cut significant portions.' },
  { id: 'lit-50', category: 'literature', difficulty: 'medium', question: 'Who wrote the science fiction novel "Dune"?', answer: 'Frank Herbert', options: ['Isaac Asimov', 'Arthur C. Clarke', 'Frank Herbert', 'Robert Heinlein'], explanation: 'Frank Herbert published Dune in 1965 after it was rejected by over 20 publishers. It won both the Hugo and Nebula Awards and is the best-selling science fiction novel of all time.' },
  { id: 'lit-51', category: 'literature', difficulty: 'medium', question: 'What Charles Dickens novel features the orphan Pip?', answer: 'Great Expectations', options: ['Oliver Twist', 'David Copperfield', 'Great Expectations', 'Bleak House'], explanation: 'Dickens published Great Expectations as a serial in 1860-1861. Pip (Philip Pirrip) is a poor orphan who receives a fortune from a mysterious benefactor, which turns out to be the convict Magwitch.' },
  { id: 'lit-52', category: 'literature', difficulty: 'medium', question: 'Which poet wrote "Leaves of Grass"?', answer: 'Walt Whitman', options: ['Walt Whitman', 'Robert Frost', 'Emily Dickinson', 'Henry Wadsworth Longfellow'], explanation: 'Whitman self-published Leaves of Grass in 1855 and continued revising it throughout his life. Ralph Waldo Emerson wrote to him saying, "I greet you at the beginning of a great career."' },
  { id: 'lit-53', category: 'literature', difficulty: 'medium', question: 'What novel by Margaret Atwood depicts a theocratic dystopia called Gilead?', answer: 'The Handmaid\'s Tale', options: ['The Handmaid\'s Tale', 'Oryx and Crake', 'The Blind Assassin', 'Alias Grace'], explanation: 'Atwood published The Handmaid\'s Tale in 1985. She has said every element in the book has a historical precedent, drawing from real-world totalitarian regimes and religious extremism.' },
  { id: 'lit-54', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Picture of Dorian Gray"?', answer: 'Oscar Wilde', options: ['Oscar Wilde', 'Henry James', 'Thomas Hardy', 'Robert Louis Stevenson'], explanation: 'Oscar Wilde published The Picture of Dorian Gray in 1890, his only novel. The story of a man whose portrait ages while he remains young was considered scandalous and was used against Wilde at his trial.' },
  { id: 'lit-55', category: 'literature', difficulty: 'medium', question: 'What is the name of Captain Ahab\'s ship in "Moby-Dick"?', answer: 'The Pequod', options: ['The Endurance', 'The Pequod', 'The Bounty', 'The Endeavour'], explanation: 'The Pequod is named after the Pequot Native American tribe of Massachusetts. Melville filled the novel with symbolic names — Ishmael is a biblical outcast, and Ahab was a wicked Old Testament king.' },
  { id: 'lit-56', category: 'literature', difficulty: 'medium', question: 'Who wrote "Catch-22"?', answer: 'Joseph Heller', options: ['Kurt Vonnegut', 'Joseph Heller', 'Norman Mailer', 'Tim O\'Brien'], explanation: 'Heller published Catch-22 in 1961, set during World War II. The title has entered everyday language to describe a no-win paradoxical situation where contradictory rules prevent any resolution.' },
  { id: 'lit-57', category: 'literature', difficulty: 'medium', question: 'Which author wrote "The Handmaid\'s Tale" and won the Booker Prize for "The Blind Assassin"?', answer: 'Margaret Atwood', options: ['Margaret Atwood', 'Toni Morrison', 'Doris Lessing', 'Hilary Mantel'], explanation: 'Atwood won the Booker Prize in 2000 for The Blind Assassin. She is a Canadian author who has written over 50 books spanning novels, poetry, and essays across a career of more than five decades.' },
  { id: 'lit-58', category: 'literature', difficulty: 'medium', question: 'What novel features the line "It was a bright cold day in April, and the clocks were striking thirteen"?', answer: '1984', options: ['Brave New World', '1984', 'Fahrenheit 451', 'A Clockwork Orange'], explanation: 'This is the opening line of George Orwell\'s 1984. The thirteen-hour clock immediately signals that something is off about this world, establishing the novel\'s totalitarian setting.' },
  { id: 'lit-59', category: 'literature', difficulty: 'medium', question: 'Who wrote "Crime and Punishment"?', answer: 'Fyodor Dostoevsky', options: ['Leo Tolstoy', 'Fyodor Dostoevsky', 'Anton Chekhov', 'Ivan Turgenev'], explanation: 'Dostoevsky published Crime and Punishment in 1866. The novel follows Raskolnikov, a former student who murders a pawnbroker and grapples with guilt and moral redemption in St. Petersburg.' },
  { id: 'lit-60', category: 'literature', difficulty: 'medium', question: 'What Toni Morrison novel tells the story of a formerly enslaved woman haunted by her dead daughter?', answer: 'Beloved', options: ['Song of Solomon', 'Beloved', 'The Bluest Eye', 'Sula'], explanation: 'Morrison published Beloved in 1987, winning the Pulitzer Prize for Fiction in 1988. She won the Nobel Prize in Literature in 1993, becoming the first African American woman to receive the honor.' },
  { id: 'lit-61', category: 'literature', difficulty: 'medium', question: 'What classic science fiction novel features the Three Laws of Robotics?', answer: 'I, Robot', options: ['I, Robot', 'Brave New World', '2001: A Space Odyssey', 'The War of the Worlds'], explanation: 'Isaac Asimov first introduced the Three Laws of Robotics in his 1942 short story "Runaround," later collected in I, Robot (1950). The first law states that a robot may not injure a human being or allow a human to come to harm through inaction.' },
  { id: 'lit-62', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Bell Jar"?', answer: 'Sylvia Plath', options: ['Virginia Woolf', 'Sylvia Plath', 'Anne Sexton', 'Dorothy Parker'], explanation: 'Sylvia Plath published The Bell Jar in 1963 under the pseudonym Victoria Lucas, just one month before her death. It is a semi-autobiographical novel about a young woman\'s descent into mental illness.' },
  { id: 'lit-63', category: 'literature', difficulty: 'medium', question: 'What banned book by Vladimir Nabokov tells the story of Humbert Humbert?', answer: 'Lolita', options: ['Ada or Ardor', 'Pale Fire', 'Lolita', 'Pnin'], explanation: 'Nabokov published Lolita in 1955 in Paris after American publishers refused it. Despite the controversial subject matter, it is considered one of the greatest novels of the 20th century for its prose.' },
  { id: 'lit-64', category: 'literature', difficulty: 'medium', question: 'Which Shakespeare play features three witches?', answer: 'Macbeth', options: ['Hamlet', 'The Tempest', 'Macbeth', 'A Midsummer Night\'s Dream'], explanation: 'The three witches (or "Weird Sisters") open Macbeth with "When shall we three meet again?" Their prophecies drive Macbeth\'s ambition and downfall. Actors traditionally call it "the Scottish play" to avoid bad luck.' },
  { id: 'lit-65', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Count of Monte Cristo"?', answer: 'Alexandre Dumas', options: ['Victor Hugo', 'Alexandre Dumas', 'Gustave Flaubert', 'Honore de Balzac'], explanation: 'Dumas published The Count of Monte Cristo as a serial from 1844-1846. Dumas also wrote The Three Musketeers and employed a team of ghostwriters, though he remained the primary creative force.' },
  { id: 'lit-66', category: 'literature', difficulty: 'medium', question: 'What novel by George Orwell is an allegorical tale about a farm where animals overthrow their human owner?', answer: 'Animal Farm', options: ['1984', 'Animal Farm', 'Down and Out in Paris and London', 'Coming Up for Air'], explanation: 'Orwell published Animal Farm in 1945 as a satire of the Russian Revolution and Stalinism. The famous line "All animals are equal, but some animals are more equal than others" critiques political hypocrisy.' },
  { id: 'lit-67', category: 'literature', difficulty: 'medium', question: 'Which author won the first Nobel Prize in Literature in 1901?', answer: 'Sully Prudhomme', options: ['Leo Tolstoy', 'Sully Prudhomme', 'Rudyard Kipling', 'Henrik Ibsen'], explanation: 'French poet Sully Prudhomme won the first Nobel Prize in Literature. Leo Tolstoy was widely expected to win, and many considered Prudhomme\'s selection controversial at the time.' },
  { id: 'lit-68', category: 'literature', difficulty: 'medium', question: 'In what language was "Don Quixote" originally written?', answer: 'Spanish', options: ['Portuguese', 'Italian', 'Spanish', 'French'], explanation: 'Cervantes wrote Don Quixote in Spanish, published in two parts in 1605 and 1615. It is considered the most influential work of literature from the Spanish Golden Age and one of the first modern novels.' },
  { id: 'lit-69', category: 'literature', difficulty: 'medium', question: 'Who wrote "Invisible Man" (1952)?', answer: 'Ralph Ellison', options: ['Ralph Ellison', 'James Baldwin', 'Richard Wright', 'H.G. Wells'], explanation: 'Ralph Ellison published Invisible Man in 1952, winning the National Book Award in 1953. Not to be confused with H.G. Wells\' "The Invisible Man" (1897), Ellison\'s novel explores racial identity in America.' },
  { id: 'lit-70', category: 'literature', difficulty: 'medium', question: 'What novel by Harper Lee was published in 2015 as a sequel to "To Kill a Mockingbird"?', answer: 'Go Set a Watchman', options: ['Go Set a Watchman', 'The Mockingbird\'s Song', 'Scout\'s Honor', 'Maycomb'], explanation: 'Go Set a Watchman was actually written before To Kill a Mockingbird, around 1957. Its publication was controversial because Lee\'s mental state and whether she truly consented to publication were questioned.' },
  { id: 'lit-71', category: 'literature', difficulty: 'medium', question: 'Who wrote "War and Peace"?', answer: 'Leo Tolstoy', options: ['Fyodor Dostoevsky', 'Leo Tolstoy', 'Anton Chekhov', 'Alexander Pushkin'], explanation: 'Tolstoy published War and Peace between 1865 and 1869. The epic novel spans over 1,200 pages and follows five aristocratic families during the Napoleonic Wars and the French invasion of Russia.' },
  { id: 'lit-72', category: 'literature', difficulty: 'medium', question: 'What Philip K. Dick novel was adapted into the film "Blade Runner"?', answer: 'Do Androids Dream of Electric Sheep?', options: ['The Man in the High Castle', 'Do Androids Dream of Electric Sheep?', 'A Scanner Darkly', 'Ubik'], explanation: 'Dick published Do Androids Dream of Electric Sheep? in 1968. Ridley Scott\'s 1982 film Blade Runner significantly changed the plot but kept the core question of what makes someone human.' },
  { id: 'lit-73', category: 'literature', difficulty: 'medium', question: 'Which poet wrote "I Wandered Lonely as a Cloud"?', answer: 'William Wordsworth', options: ['William Wordsworth', 'John Keats', 'Lord Byron', 'Percy Bysshe Shelley'], explanation: 'Wordsworth published this poem (also known as "Daffodils") in 1807. He was inspired by a walk with his sister Dorothy near Ullswater Lake in the English Lake District, where they saw a field of daffodils.' },
  { id: 'lit-74', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Scarlet Letter"?', answer: 'Nathaniel Hawthorne', options: ['Nathaniel Hawthorne', 'Herman Melville', 'Washington Irving', 'James Fenimore Cooper'], explanation: 'Hawthorne published The Scarlet Letter in 1850, set in Puritan Massachusetts. The novel follows Hester Prynne, who is forced to wear a red "A" on her chest as punishment for adultery.' },
  { id: 'lit-75', category: 'literature', difficulty: 'medium', question: 'What bestselling novel by Dan Brown features the character Robert Langdon?', answer: 'The Da Vinci Code', options: ['The Da Vinci Code', 'Inferno', 'Angels & Demons', 'The Lost Symbol'], explanation: 'Brown published The Da Vinci Code in 2003, and it sold over 80 million copies worldwide. While Angels & Demons also features Langdon, The Da Vinci Code was the massive breakout bestseller.' },
  { id: 'lit-76', category: 'literature', difficulty: 'medium', question: 'What novel by Cormac McCarthy follows a father and son through a post-apocalyptic landscape?', answer: 'The Road', options: ['Blood Meridian', 'No Country for Old Men', 'The Road', 'All the Pretty Horses'], explanation: 'McCarthy published The Road in 2006, winning the Pulitzer Prize for Fiction in 2007. He dedicated the novel to his young son John Francis McCarthy, and it was adapted into a 2009 film starring Viggo Mortensen.' },
  { id: 'lit-77', category: 'literature', difficulty: 'medium', question: 'Who wrote "Wuthering Heights"?', answer: 'Emily Bronte', options: ['Charlotte Bronte', 'Emily Bronte', 'Anne Bronte', 'Jane Austen'], explanation: 'Emily Bronte published Wuthering Heights in 1847 under the pen name Ellis Bell. It was her only novel, as she died of tuberculosis the following year at age 30. All three Bronte sisters used male pen names.' },
  { id: 'lit-78', category: 'literature', difficulty: 'medium', question: 'What classic children\'s book by L. Frank Baum features a girl named Dorothy?', answer: 'The Wonderful Wizard of Oz', options: ['Alice\'s Adventures in Wonderland', 'The Wonderful Wizard of Oz', 'Peter Pan', 'The Secret Garden'], explanation: 'Baum published The Wonderful Wizard of Oz in 1900. He went on to write 13 additional Oz books. The 1939 MGM film starring Judy Garland significantly differs from the original story in several ways.' },
  { id: 'lit-79', category: 'literature', difficulty: 'medium', question: 'What is the subtitle of Mary Shelley\'s "Frankenstein"?', answer: 'The Modern Prometheus', options: ['The Modern Prometheus', 'The Modern Monster', 'The Created Man', 'The New Adam'], explanation: 'The full title is Frankenstein; or, The Modern Prometheus. In Greek mythology, Prometheus created mankind and stole fire from the gods, paralleling Victor Frankenstein\'s act of creating life.' },
  { id: 'lit-80', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Jungle," a novel about the meatpacking industry?', answer: 'Upton Sinclair', options: ['Upton Sinclair', 'Sinclair Lewis', 'Jack London', 'Theodore Dreiser'], explanation: 'Upton Sinclair published The Jungle in 1906. While he intended it as a socialist critique of worker exploitation, the public outcry about food safety led directly to the Pure Food and Drug Act of 1906.' },
  { id: 'lit-81', category: 'literature', difficulty: 'medium', question: 'Which of these is NOT one of Shakespeare\'s comedies?', answer: 'Coriolanus', options: ['Much Ado About Nothing', 'The Merry Wives of Windsor', 'Coriolanus', 'Twelfth Night'], explanation: 'Coriolanus is one of Shakespeare\'s tragedies, based on the life of the Roman general Gaius Marcius Coriolanus. Much Ado About Nothing, The Merry Wives of Windsor, and Twelfth Night are all comedies.' },
  { id: 'lit-82', category: 'literature', difficulty: 'medium', question: 'Who wrote "On the Road"?', answer: 'Jack Kerouac', options: ['Jack Kerouac', 'Allen Ginsberg', 'William S. Burroughs', 'Neal Cassady'], explanation: 'Kerouac published On the Road in 1957, becoming the defining novel of the Beat Generation. He famously typed the first draft on a single 120-foot scroll of paper in just three weeks.' },
  { id: 'lit-83', category: 'literature', difficulty: 'medium', question: 'What novel features the character Holden Caulfield?', answer: 'The Catcher in the Rye', options: ['A Separate Peace', 'The Catcher in the Rye', 'Lord of the Flies', 'The Outsiders'], explanation: 'J.D. Salinger published The Catcher in the Rye in 1951. The novel has been associated with several acts of violence, as Mark David Chapman was carrying a copy when he killed John Lennon in 1980.' },
  { id: 'lit-84', category: 'literature', difficulty: 'medium', question: 'Which poet wrote "Stopping by Woods on a Snowy Evening"?', answer: 'Robert Frost', options: ['Robert Frost', 'Walt Whitman', 'William Butler Yeats', 'T.S. Eliot'], explanation: 'Frost published "Stopping by Woods on a Snowy Evening" in 1923 in his collection New Hampshire. Its famous closing lines are "And miles to go before I sleep, / And miles to go before I sleep."' },
  { id: 'lit-85', category: 'literature', difficulty: 'medium', question: 'What Arthur C. Clarke novel was developed simultaneously with Stanley Kubrick\'s film?', answer: '2001: A Space Odyssey', options: ['Rendezvous with Rama', '2001: A Space Odyssey', 'Childhood\'s End', 'The Fountains of Paradise'], explanation: 'Clarke and Kubrick developed the novel and screenplay together from 1964 to 1968. The novel was published after the film\'s release and differs from it in several details, including the destination planet.' },
  { id: 'lit-86', category: 'literature', difficulty: 'medium', question: 'Who is the protagonist of "Jane Eyre"?', answer: 'Jane Eyre', options: ['Jane Eyre', 'Catherine Earnshaw', 'Elizabeth Bennet', 'Dorothea Brooke'], explanation: 'Charlotte Bronte published Jane Eyre in 1847 under the pen name Currer Bell. The novel follows the orphaned Jane from her harsh childhood to her role as governess at Thornfield Hall and her love for Mr. Rochester.' },
  { id: 'lit-87', category: 'literature', difficulty: 'medium', question: 'What literary term describes a long poem that tells the story of a hero\'s adventures?', answer: 'Epic', options: ['Sonnet', 'Ballad', 'Epic', 'Ode'], explanation: 'The epic is one of the oldest literary forms, with Homer\'s Iliad and Odyssey being foundational examples. Other notable epics include Virgil\'s Aeneid, Dante\'s Divine Comedy, and Milton\'s Paradise Lost.' },
  { id: 'lit-88', category: 'literature', difficulty: 'medium', question: 'Who wrote "The Hitchhiker\'s Guide to the Galaxy"?', answer: 'Douglas Adams', options: ['Douglas Adams', 'Terry Pratchett', 'Neil Gaiman', 'Kurt Vonnegut'], explanation: 'Adams published The Hitchhiker\'s Guide to the Galaxy in 1979, adapted from his BBC radio series. The answer to "the Ultimate Question of Life, the Universe, and Everything" in the book is famously 42.' },
  { id: 'lit-89', category: 'literature', difficulty: 'medium', question: 'What pen name did the Bronte sisters use when they first published their poetry?', answer: 'Currer, Ellis, and Acton Bell', options: ['Currer, Ellis, and Acton Bell', 'George, Edward, and William Bell', 'Charles, Thomas, and James Bell', 'Arthur, Henry, and Robert Bell'], explanation: 'Charlotte was Currer Bell, Emily was Ellis Bell, and Anne was Acton Bell. They chose ambiguously gendered names because, as Charlotte later explained, they did not want their work judged by their sex.' },
  { id: 'lit-90', category: 'literature', difficulty: 'hard', question: 'What T.S. Eliot poem begins "April is the cruellest month"?', answer: 'The Waste Land', options: ['The Love Song of J. Alfred Prufrock', 'The Waste Land', 'Four Quartets', 'Ash Wednesday'], explanation: 'Eliot published The Waste Land in 1922, and it became one of the most important poems of the 20th century. The poem was heavily edited by Ezra Pound, who cut it nearly in half from its original length.' },
  { id: 'lit-91', category: 'literature', difficulty: 'hard', question: 'Who won the Nobel Prize in Literature in 2016, becoming the first musician to receive the honor?', answer: 'Bob Dylan', options: ['Leonard Cohen', 'Bob Dylan', 'Paul McCartney', 'Joni Mitchell'], explanation: 'Bob Dylan won "for having created new poetic expressions within the great American song tradition." His selection was controversial among literary purists, and he waited weeks before publicly acknowledging the prize.' },
  { id: 'lit-92', category: 'literature', difficulty: 'hard', question: 'What is the first line of "Moby-Dick"?', answer: 'Call me Ishmael.', options: ['It was a dark and stormy night.', 'Call me Ishmael.', 'In the beginning was the Word.', 'It is a truth universally acknowledged.'], explanation: '"Call me Ishmael" is arguably the most famous opening line in American literature. Melville\'s narrator never confirms whether Ishmael is his real name, adding ambiguity from the very first sentence.' },
  { id: 'lit-93', category: 'literature', difficulty: 'hard', question: 'Which Gabriel Garcia Marquez novel tells the story of an unrequited love that lasts over fifty years?', answer: 'Love in the Time of Cholera', options: ['One Hundred Years of Solitude', 'Love in the Time of Cholera', 'Chronicle of a Death Foretold', 'The Autumn of the Patriarch'], explanation: 'Garcia Marquez published Love in the Time of Cholera in 1985. The story was partly inspired by the courtship of his own parents, and the main characters finally unite in old age after decades apart.' },
  { id: 'lit-94', category: 'literature', difficulty: 'hard', question: 'What James Joyce novel takes place entirely on June 16, 1904, in Dublin?', answer: 'Ulysses', options: ['Dubliners', 'A Portrait of the Artist as a Young Man', 'Ulysses', 'Finnegans Wake'], explanation: 'Joyce published Ulysses in 1922. June 16 is now celebrated annually as "Bloomsday" after the protagonist Leopold Bloom. The novel parallels Homer\'s Odyssey, with each chapter corresponding to an episode.' },
  { id: 'lit-95', category: 'literature', difficulty: 'hard', question: 'Who wrote "The Divine Comedy"?', answer: 'Dante Alighieri', options: ['Dante Alighieri', 'Giovanni Boccaccio', 'Francesco Petrarch', 'Niccolo Machiavelli'], explanation: 'Dante wrote The Divine Comedy between 1308 and 1321 in Italian rather than Latin, which was revolutionary. The epic poem follows the author through Hell (Inferno), Purgatory (Purgatorio), and Heaven (Paradiso).' },
  { id: 'lit-96', category: 'literature', difficulty: 'hard', question: 'What Russian novel features the characters Levin and Anna, who have parallel storylines?', answer: 'Anna Karenina', options: ['War and Peace', 'Anna Karenina', 'The Brothers Karamazov', 'Eugene Onegin'], explanation: 'Tolstoy published Anna Karenina in serial form from 1875 to 1877. Its famous opening line is "Happy families are all alike; every unhappy family is unhappy in its own way."' },
  { id: 'lit-97', category: 'literature', difficulty: 'hard', question: 'What William Faulkner novel is told from the perspectives of four different narrators, including one with an intellectual disability?', answer: 'The Sound and the Fury', options: ['As I Lay Dying', 'The Sound and the Fury', 'Absalom, Absalom!', 'Light in August'], explanation: 'Faulkner published The Sound and the Fury in 1929. The first section is narrated by Benjy Compson, whose nonlinear perception of time makes it one of the most challenging openings in American literature.' },
  { id: 'lit-98', category: 'literature', difficulty: 'hard', question: 'What is the name of the imaginary country in Voltaire\'s "Candide" where the streets are paved with gold?', answer: 'El Dorado', options: ['Utopia', 'El Dorado', 'Lilliput', 'Brobdingnag'], explanation: 'In Candide (1759), El Dorado is a hidden South American paradise with no courts, prisons, or poverty. Voltaire used it to satirize both European greed and the philosophical optimism of Leibniz.' },
  { id: 'lit-99', category: 'literature', difficulty: 'hard', question: 'Which author wrote "Mrs. Dalloway" and "To the Lighthouse"?', answer: 'Virginia Woolf', options: ['Virginia Woolf', 'Edith Wharton', 'Katherine Mansfield', 'Gertrude Stein'], explanation: 'Woolf published Mrs. Dalloway in 1925 and To the Lighthouse in 1927. She was a central figure in the Bloomsbury Group and a pioneer of the stream-of-consciousness narrative technique.' },
  { id: 'lit-100', category: 'literature', difficulty: 'hard', question: 'What is the pen name of Polish-born author Józef Teodor Konrad Korzeniowski?', answer: 'Joseph Conrad', options: ['Joseph Conrad', 'George Orwell', 'Lewis Carroll', 'Mark Twain'], explanation: 'Joseph Conrad wrote in English, his third language after Polish and French. He is best known for Heart of Darkness (1899), which inspired Francis Ford Coppola\'s film Apocalypse Now.' },
  { id: 'lit-101', category: 'literature', difficulty: 'hard', question: 'What Haruki Murakami novel features two parallel storylines set in 1984 Japan?', answer: '1Q84', options: ['Kafka on the Shore', '1Q84', 'Norwegian Wood', 'The Wind-Up Bird Chronicle'], explanation: 'Murakami published 1Q84 in three volumes between 2009 and 2010. The title is a play on 1984 — in Japanese, the number 9 is pronounced "kyu," which sounds similar to the letter Q.' },
  { id: 'lit-102', category: 'literature', difficulty: 'hard', question: 'Who wrote "Middlemarch," considered one of the greatest English novels?', answer: 'George Eliot', options: ['George Eliot', 'Thomas Hardy', 'Anthony Trollope', 'Charles Dickens'], explanation: 'George Eliot (Mary Ann Evans) published Middlemarch in serial form in 1871-1872. She used a male pen name to ensure her work would be taken seriously and not dismissed as mere "feminine romance."' },
  { id: 'lit-103', category: 'literature', difficulty: 'hard', question: 'What Samuel Beckett play features two characters waiting for someone who never arrives?', answer: 'Waiting for Godot', options: ['Endgame', 'Waiting for Godot', 'Happy Days', 'Krapp\'s Last Tape'], explanation: 'Beckett wrote Waiting for Godot in French (En attendant Godot) and it premiered in 1953. The play is a cornerstone of the Theatre of the Absurd, and Beckett won the Nobel Prize in Literature in 1969.' },
  { id: 'lit-104', category: 'literature', difficulty: 'hard', question: 'Which Dostoevsky novel explores the philosophical conflict among brothers Dmitri, Ivan, and Alyosha?', answer: 'The Brothers Karamazov', options: ['Crime and Punishment', 'The Idiot', 'The Brothers Karamazov', 'Demons'], explanation: 'Dostoevsky published The Brothers Karamazov in 1880, his final novel. It contains the famous "Grand Inquisitor" parable and was deeply influential on existentialist philosophy and theology.' },
  { id: 'lit-105', category: 'literature', difficulty: 'hard', question: 'What is the longest novel ever written in terms of word count?', answer: 'In Search of Lost Time', options: ['War and Peace', 'In Search of Lost Time', 'Les Miserables', 'Don Quixote'], explanation: 'Marcel Proust\'s In Search of Lost Time (A la recherche du temps perdu) contains approximately 1.2 million words across seven volumes. It was published between 1913 and 1927, with the last three volumes published posthumously.' },
  { id: 'lit-106', category: 'literature', difficulty: 'hard', question: 'Who wrote the epic poem "Paradise Lost"?', answer: 'John Milton', options: ['John Milton', 'Edmund Spenser', 'Geoffrey Chaucer', 'Alexander Pope'], explanation: 'Milton published Paradise Lost in 1667. He dictated the entire 10,000-line epic to scribes because he had gone completely blind by 1654. The poem retells Satan\'s rebellion and the Fall of Man.' },
  { id: 'lit-107', category: 'literature', difficulty: 'hard', question: 'What novel by Kazuo Ishiguro features a butler reflecting on his life of service?', answer: 'The Remains of the Day', options: ['Never Let Me Go', 'The Remains of the Day', 'An Artist of the Floating World', 'The Buried Giant'], explanation: 'Ishiguro published The Remains of the Day in 1989, winning the Booker Prize. He won the Nobel Prize in Literature in 2017. The novel was adapted into a 1993 film starring Anthony Hopkins and Emma Thompson.' },
  { id: 'lit-108', category: 'literature', difficulty: 'hard', question: 'Which ancient Greek playwright wrote "Oedipus Rex"?', answer: 'Sophocles', options: ['Euripides', 'Aeschylus', 'Sophocles', 'Aristophanes'], explanation: 'Sophocles wrote Oedipus Rex (Oedipus the King) around 429 BC. Aristotle considered it the perfect tragedy in his Poetics. Freud later named the "Oedipus complex" after this story.' },
  { id: 'lit-109', category: 'literature', difficulty: 'hard', question: 'What Jorge Luis Borges story describes a library containing every possible book?', answer: 'The Library of Babel', options: ['The Garden of Forking Paths', 'The Library of Babel', 'Tlon, Uqbar, Orbis Tertius', 'The Aleph'], explanation: 'Borges published "The Library of Babel" in 1941. The library contains all possible 410-page books using 25 characters, meaning it holds every book that could ever be written — along with infinite nonsense.' },
  { id: 'lit-110', category: 'literature', difficulty: 'hard', question: 'Who wrote "Beloved," a novel inspired by the true story of Margaret Garner?', answer: 'Toni Morrison', options: ['Alice Walker', 'Toni Morrison', 'Maya Angelou', 'Zora Neale Hurston'], explanation: 'Morrison based Beloved (1987) on the true story of Margaret Garner, an enslaved woman who killed her own daughter rather than have her returned to slavery. Morrison won the Nobel Prize in Literature in 1993.' },
  { id: 'lit-111', category: 'literature', difficulty: 'hard', question: 'What is the Canterbury Tales written in?', answer: 'Middle English', options: ['Old English', 'Middle English', 'Early Modern English', 'Latin'], explanation: 'Geoffrey Chaucer wrote The Canterbury Tales in Middle English between 1387 and 1400. It was groundbreaking because most literary works of the time were written in Latin or French, not the vernacular English.' },
  { id: 'lit-112', category: 'literature', difficulty: 'hard', question: 'Which novel by Salman Rushdie led to a fatwa calling for his death in 1989?', answer: 'The Satanic Verses', options: ['Midnight\'s Children', 'The Satanic Verses', 'Shame', 'The Moor\'s Last Sigh'], explanation: 'Rushdie published The Satanic Verses in 1988. Iran\'s Ayatollah Khomeini issued a fatwa in 1989, forcing Rushdie into hiding for nearly a decade. He was stabbed onstage in New York in August 2022.' },
  { id: 'lit-113', category: 'literature', difficulty: 'hard', question: 'What form of Japanese poetry consists of three lines with a 5-7-5 syllable structure?', answer: 'Haiku', options: ['Tanka', 'Haiku', 'Senryu', 'Renga'], explanation: 'Haiku evolved from the opening stanza of a longer collaborative poem called renga. Matsuo Basho (1644-1694) is considered the greatest haiku poet. His most famous haiku is about a frog jumping into an old pond.' },
  { id: 'lit-114', category: 'literature', difficulty: 'hard', question: 'Which author wrote "Infinite Jest"?', answer: 'David Foster Wallace', options: ['Thomas Pynchon', 'David Foster Wallace', 'Don DeLillo', 'Jonathan Franzen'], explanation: 'Wallace published Infinite Jest in 1996. The 1,079-page novel (with 388 endnotes) is set in a near-future North America and weaves together stories about a tennis academy and a drug rehabilitation center.' },
  { id: 'lit-115', category: 'literature', difficulty: 'hard', question: 'What novel by Chinua Achebe is considered the foundational work of modern African literature?', answer: 'Things Fall Apart', options: ['Things Fall Apart', 'No Longer at Ease', 'Arrow of God', 'A Man of the People'], explanation: 'Achebe published Things Fall Apart in 1958, set in pre-colonial Nigeria. The title comes from W.B. Yeats\' poem "The Second Coming." It has sold over 20 million copies and been translated into 57 languages.' },
  { id: 'lit-116', category: 'literature', difficulty: 'hard', question: 'Who wrote "The Master and Margarita," a novel suppressed in the Soviet Union?', answer: 'Mikhail Bulgakov', options: ['Mikhail Bulgakov', 'Boris Pasternak', 'Alexander Solzhenitsyn', 'Mikhail Sholokhov'], explanation: 'Bulgakov wrote The Master and Margarita between 1928 and 1940 but it was not published until 1966, 26 years after his death. The novel features the Devil visiting atheist Soviet Moscow with a giant talking cat named Behemoth.' },
  { id: 'lit-117', category: 'literature', difficulty: 'hard', question: 'What William Gibson novel is credited with popularizing the term "cyberspace"?', answer: 'Neuromancer', options: ['Neuromancer', 'Count Zero', 'Pattern Recognition', 'Burning Chrome'], explanation: 'Gibson published Neuromancer in 1984, and it won the Hugo, Nebula, and Philip K. Dick Awards — a rare "triple crown" of science fiction. Gibson coined "cyberspace" in his 1982 short story "Burning Chrome" but Neuromancer popularized it.' },
  { id: 'lit-118', category: 'literature', difficulty: 'hard', question: 'What banned novel by James Joyce was the subject of a landmark 1933 obscenity trial in the United States?', answer: 'Ulysses', options: ['Dubliners', 'Ulysses', 'Finnegans Wake', 'A Portrait of the Artist as a Young Man'], explanation: 'Ulysses was banned in the US from 1921 to 1933. Judge John M. Woolsey ruled it was not obscene, calling it a "sincere and honest book." The case, United States v. One Book Called Ulysses, was a landmark for free speech.' },
  { id: 'lit-119', category: 'literature', difficulty: 'hard', question: 'Which Hugo and Nebula Award-winning novel by Michael Chabon is set in an alternate history where a Jewish settlement is established in Alaska?', answer: 'The Yiddish Policemen\'s Union', options: ['The Amazing Adventures of Kavalier & Clay', 'The Yiddish Policemen\'s Union', 'Wonder Boys', 'Telegraph Avenue'], explanation: 'Chabon published The Yiddish Policemen\'s Union in 2007. It won both the Hugo and Nebula Awards. His Pulitzer Prize winner was a different novel, The Amazing Adventures of Kavalier & Clay (2001).' },
  { id: 'lit-120', category: 'literature', difficulty: 'hard', question: 'What ancient Mesopotamian text is considered the oldest surviving great work of literature?', answer: 'The Epic of Gilgamesh', options: ['The Code of Hammurabi', 'The Epic of Gilgamesh', 'The Iliad', 'The Book of the Dead'], explanation: 'The Epic of Gilgamesh dates to approximately 2100 BC from ancient Sumer. It tells the story of King Gilgamesh of Uruk and includes a flood narrative that predates and closely parallels the biblical story of Noah.' },
  { id: 'lit-121', category: 'literature', difficulty: 'hard', question: 'Who wrote "One Day in the Life of Ivan Denisovich," based on his experience in Soviet labor camps?', answer: 'Aleksandr Solzhenitsyn', options: ['Aleksandr Solzhenitsyn', 'Boris Pasternak', 'Mikhail Bulgakov', 'Vasily Grossman'], explanation: 'Solzhenitsyn published the novella in 1962 during Khrushchev\'s "thaw." He spent eight years in Soviet labor camps. He won the Nobel Prize in Literature in 1970 but was expelled from the USSR in 1974.' },
  { id: 'lit-122', category: 'literature', difficulty: 'hard', question: 'What novel by Umberto Eco is a murder mystery set in a 14th-century Italian monastery?', answer: 'The Name of the Rose', options: ['Foucault\'s Pendulum', 'The Name of the Rose', 'Baudolino', 'The Island of the Day Before'], explanation: 'Eco published The Name of the Rose in 1980. Despite being a dense novel full of Latin passages and medieval philosophy, it became a worldwide bestseller, selling over 50 million copies.' },
  { id: 'lit-123', category: 'literature', difficulty: 'hard', question: 'Which Nobel Prize-winning author wrote "The Stranger" and "The Plague"?', answer: 'Albert Camus', options: ['Jean-Paul Sartre', 'Albert Camus', 'Andre Gide', 'Samuel Beckett'], explanation: 'Camus published The Stranger in 1942 and The Plague in 1947. He won the Nobel Prize in Literature in 1957 at age 44. Though often called an existentialist, he rejected the label, preferring "absurdist."' },
  { id: 'lit-124', category: 'literature', difficulty: 'hard', question: 'What Kurt Vonnegut novel features the fictional substance "ice-nine"?', answer: 'Cat\'s Cradle', options: ['Slaughterhouse-Five', 'Cat\'s Cradle', 'Breakfast of Champions', 'The Sirens of Titan'], explanation: 'Vonnegut published Cat\'s Cradle in 1963. Ice-nine is a form of water that freezes at room temperature and could destroy all life on Earth. Vonnegut credited the idea to a conversation about Irving Langmuir at General Electric.' },
  { id: 'lit-125', category: 'literature', difficulty: 'hard', question: 'What is the name of the fictional language invented by Anthony Burgess for "A Clockwork Orange"?', answer: 'Nadsat', options: ['Newspeak', 'Nadsat', 'Elvish', 'Lapine'], explanation: 'Burgess published A Clockwork Orange in 1962 using Nadsat, a slang based heavily on Russian. The word "nadsat" itself is Russian for "-teen" (as in thirteen, fourteen). Burgess was a trained linguist who spoke several languages.' },
]
